import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const d=JSON.parse('{"title":"GitHub and previews","description":"","frontmatter":{},"headers":[],"relativePath":"guide/github.md","filePath":"guide/github.md"}'),i={name:"guide/github.md"};function r(a,e,l,h,p,u){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="github-and-previews" tabindex="-1">GitHub and previews <a class="header-anchor" href="#github-and-previews" aria-label="Permalink to &quot;GitHub and previews&quot;">​</a></h1><h2 id="connecting" tabindex="-1">Connecting GitHub <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting GitHub {#connecting}&quot;">​</a></h2><p>The first time you connect GitHub, Orbit asks GitHub to create an App for this server. When you install it, GitHub asks where (your account or one of your organizations), and the App can only read the repositories you choose there.</p><ul><li><strong>Why the App is public:</strong> GitHub only installs a private App on the account that created it. Public only means it can be installed elsewhere. Anyone can see its page, but its key stays on your server, and Orbit only uses the installation that the GitHub user connecting from your console confirms.</li><li><strong>Owned by an organization:</strong> Orbit can create the App under an organization (&quot;Have an organization own the App instead&quot;) if the organization wants it in its own settings.</li><li><strong>Name and logo:</strong> the App is named &quot;Orbit &lt;server name&gt;&quot;, which you can change before creating it; GitHub requires a name no other App uses. GitHub only accepts a logo through the App&#39;s settings page, so Settings → Integrations offers Orbit&#39;s logo and links to that page.</li><li><strong>One installation at a time:</strong> to read another account&#39;s repositories, disconnect and connect again, choosing that account.</li><li><strong>Addresses:</strong> GitHub sends you back to the address you used when you created the App, so create it from <code>https://orbit.&lt;server-ip-with-dashes&gt;.sslip.io</code> rather than through an SSH tunnel. If you later reach Orbit at another address, update the App&#39;s callback URL on GitHub to <code>&lt;new address&gt;/github/callback</code>.</li><li><strong>Where its key lives:</strong> the App&#39;s private key and secrets are sealed in Orbit&#39;s secret store and travel with <code>orbit backup</code>. Disconnecting forgets the installation but keeps the App. Deleting the App on GitHub makes Orbit create a new one the next time you connect.</li></ul><h2 id="push" tabindex="-1">Deploying on push <a class="header-anchor" href="#push" aria-label="Permalink to &quot;Deploying on push {#push}&quot;">​</a></h2><ul><li>The App sends every push to <code>https://orbit.&lt;server-ip-with-dashes&gt;.sslip.io/github/webhook</code>, signed with a secret only your server knows.</li><li>A push to an application&#39;s branch deploys that commit when <strong>Deploy automatically</strong> is on in the application&#39;s settings. The same delivery twice deploys once.</li><li>For Apps created by older versions, turn on their <strong>Push</strong> event on GitHub (Permissions &amp; events → Subscribe to events); Settings → Integrations says so while it is off.</li></ul><h2 id="previews" tabindex="-1">Pull request previews <a class="header-anchor" href="#previews" aria-label="Permalink to &quot;Pull request previews {#previews}&quot;">​</a></h2><p>Turn previews on in a project&#39;s <strong>Previews</strong>, next to its environments, and choose the long-lived environment they copy and how many can run at once (3 by default, at most 10).</p><p>Every pull request opened from a branch of a repository that environment builds gets a preview named after it (<code>pr-12</code>):</p><ul><li>the services built from that repository, deployed from the pull request&#39;s branch, with the source&#39;s variables and secrets;</li><li>empty copies of the databases those services reference, without backups, so a preview never reads or writes your real data;</li><li>its own namespace and generated address (<code>&lt;service&gt;-pr-12-&lt;project&gt;.&lt;server-ip-with-dashes&gt;.sslip.io</code>), or <code>pr-12.&lt;domain&gt;</code> once previews have <a href="./cloudflare#previews">a domain of yours in Cloudflare</a>.</li></ul><p>Pushes to the branch redeploy the preview. Closing or merging the pull request removes it with its data, and <strong>Remove</strong> does the same by hand.</p><ul><li><strong>Forks:</strong> pull requests from forks never get a preview, so code from outside the repository never runs on your servers.</li><li><strong>The limit:</strong> past it, a pull request gets its preview on its next push once another one closes. Turning previews off keeps the open ones until their pull requests close.</li><li><strong>Older Apps:</strong> previews need <strong>Pull requests: read</strong> and the <strong>Pull request</strong> event. Add both on GitHub (Permissions &amp; events), then accept the new permission on the installation; the Previews page says so while the event is missing.</li></ul>',12)])])}const g=t(i,[["render",r]]);export{d as __pageData,g as default};
